"""L10M closed-loop target policy with safety gating and bounded hysteresis."""


# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use confirmed target tracking, conservative steering, and stable reacquisition."""

    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    last_action = memory.get("last_action", "")
    turn_hold = int(memory.get("turn_hold", 0))
    verified = bool(memory.get("verified", False))

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    heading_error = float(observation["heading_error"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])

    def emit(action, confidence, next_state):
        memory["state"] = next_state
        memory["last_action"] = action
        memory["turn_hold"] = 1 if action in {"VEER_LEFT", "VEER_RIGHT"} else 0
        return action, confidence, memory

    # Safety is an unconditional hard gate.
    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    confirmed = (
        visible
        and target_confidence >= 0.55
        and identity_confidence >= 0.60
    )

    if not confirmed:
        memory["verified"] = False
        memory["turn_hold"] = 0
        if lost_steps <= 1:
            return emit("STOP", 0.92, "REACQUIRE")
        # Hold each scan direction for two frames to avoid rapid oscillation.
        if lost_steps % 2 == 0:
            scan_direction = (
                "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
            )
        memory["scan_direction"] = scan_direction
        return emit(scan_direction, 0.75, "SEARCH")

    # Require one cautious confirmation step after a fresh track appears.
    if track_age < 2 and not verified:
        memory["verified"] = True
        return emit("SLOW_DOWN", 0.80, "VERIFY")
    memory["verified"] = True

    if (
        distance == "near"
        and abs(heading_error) <= 12.0
        and target_confidence >= 0.70
        and identity_confidence >= 0.80
    ):
        return emit("ARRIVED", 0.96, "ARRIVED")

    # Bearing is primary; heading error breaks ties when nearly centered.
    signal = bearing if abs(bearing) >= 8.0 else heading_error
    desired = ""
    if signal < -14.0:
        desired = "VEER_LEFT"
    elif signal > 14.0:
        desired = "VEER_RIGHT"

    # Briefly retain a turn across noisy sign changes.
    if (
        turn_hold > 0
        and last_action in {"VEER_LEFT", "VEER_RIGHT"}
        and abs(signal) >= 8.0
    ):
        desired = last_action
        turn_hold -= 1
    memory["turn_hold"] = max(0, turn_hold)

    if desired == "VEER_LEFT" and observation["corridor_left"]:
        return emit("VEER_LEFT", 0.89, "APPROACH")
    if desired == "VEER_RIGHT" and observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.89, "APPROACH")
    if observation["corridor_center"]:
        return emit("FORWARD", 0.90, "APPROACH")
    if observation["corridor_left"]:
        return emit("VEER_LEFT", 0.82, "APPROACH")
    if observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.82, "APPROACH")
    return emit("STOP", 0.98, "STOPPED")


# EVOLVE-BLOCK-END
